import struct
lobby=bytes.fromhex('')
world=bytes.fromhex('')
print('lobby len',len(lobby),'world len',len(world))
# find first differing byte after the 4-byte header i
for i,(a,b) in enumerate(zip(lobby,world)):
    if a!=b:
        print('first diff at',i,'lobby',lobby[i:i+16].hex(),'world',world[i:i+16].hex())
        break
print('lobby common prefix len', next((i for i,(a,b) in enumerate(zip(lobby,world)) if a!=b), len(lobby)))
